<script setup lang="ts">
import {onMounted,ref,watch} from 'vue'
import {allPages,api,message} from '../api'
import {dateTime,statusNames,type Delivery,type Identity} from '../types'
import {session} from '../session'
import {useList} from '../useList'
import Icon from '../components/Icon.vue'
import Modal from '../components/Modal.vue'
import PageState from '../components/PageState.vue'
import Pagination from '../components/Pagination.vue'
const {data,loading,error,load}=useList<Delivery>();const page=ref(0);const status=ref('');const open=ref(false);const busy=ref(false);const actionError=ref('');const formError=ref('')
const form=ref({recipientId:'',title:'',body:''});let eventId=''
const members=ref<Identity[]>([])
function reload(){return load(`/deliveries?page=${page.value}&size=20&status=${status.value}`)};watch(page,reload);watch(status,()=>{page.value=0;void reload()});onMounted(reload)
async function show(){form.value={recipientId:session.user?.id??'',title:'',body:''};formError.value='';eventId=crypto.randomUUID();open.value=true;try{members.value=await allPages<Identity>('/users')}catch(e){formError.value=message(e)}}
async function save(){busy.value=true;formError.value='';try{await api('/deliveries','POST',{...form.value,eventId,objectType:'ANNOUNCEMENT',objectId:eventId});open.value=false;await reload()}catch(e){formError.value=message(e)}finally{busy.value=false}}
async function retry(id:string){busy.value=true;actionError.value='';try{await api(`/deliveries/${id}/retry`,'POST');await reload()}catch(e){actionError.value=message(e)}finally{busy.value=false}}
</script>
<template><div class="page-heading"><div><div class="eyebrow">MESSAGING / DELIVERY</div><h1>通知投递</h1><p>从事件接收到送达，每一步都有记录。</p></div><button class="button" @click="show"><Icon name="plus" :size="17"/>发送站内信</button></div><div class="info-strip"><Icon name="send" :size="18"/><p>站内信在后台投递；失败自动重试，累计五次后进入失败队列。重新启用收件人后可手动重试。</p></div><p v-if="actionError" class="form-error" role="alert">{{actionError}}</p><section class="panel"><div class="toolbar"><label class="inline-label">投递状态<select v-model="status"><option value="">全部状态</option><option v-for="(label,key) in statusNames" :key="key" :value="key">{{label}}</option></select></label><button class="text-link" @click="reload"><Icon name="refresh" :size="16"/>刷新</button></div><PageState :loading="loading" :error="error" :empty="!data.items.length" empty-text="暂无投递记录" @retry="reload"><div class="table-scroll"><table><thead><tr><th>通知 / 来源</th><th>收件人编号</th><th>状态</th><th>尝试次数</th><th>创建时间</th><th class="align-right">操作</th></tr></thead><tbody><tr v-for="task in data.items" :key="task.id"><td><strong>{{task.title}}</strong><small class="subtext">{{task.source}} · {{task.eventId}}</small></td><td class="mono short-id" :title="task.recipientId">{{task.recipientId}}</td><td><span class="badge" :class="{warning:task.status==='RETRY'||task.status==='PENDING',danger:task.status==='DEAD'}">{{statusNames[task.status]}}</span><small v-if="task.lastError" class="subtext">{{task.lastError==='RECIPIENT_DISABLED'?'收件人账号已停用':task.lastError}}</small><small v-if="task.status==='RETRY'" class="subtext">下次 {{dateTime(task.nextAttemptAt)}}</small></td><td>{{task.attempts}}</td><td class="nowrap muted">{{dateTime(task.createdAt)}}</td><td class="align-right"><button v-if="['DEAD','RETRY'].includes(task.status)" class="text-link" :disabled="busy" @click="retry(task.id)">重新投递</button><span v-else class="muted">—</span></td></tr></tbody></table></div><Pagination :page="page" :total="data.total" :size="20" @change="page=$event"/></PageState></section><Modal v-if="open" title="发送站内信" @close="open=false"><form class="form-body" @submit.prevent="save"><label>收件人<select v-model="form.recipientId" required><option v-for="member in members" :key="member.id" :value="member.id">{{member.displayName}} · {{member.username}}{{member.active?'':'（已停用）'}}</option></select><small>默认发送给自己；停用账号的投递将进入重试队列。</small></label><label>通知标题<input v-model="form.title" required maxlength="100"></label><label>通知正文<textarea v-model="form.body" rows="5" required maxlength="2000"/><small>仅发送与校园服务有关的信息，不填写密码或令牌。</small></label><p v-if="formError" class="form-error" role="alert">{{formError}}</p><div class="form-actions"><button type="button" class="button secondary" @click="open=false">取消</button><button class="button" :disabled="busy">{{busy?'正在发送…':'加入投递队列'}}</button></div></form></Modal></template>
